{
  "corrected": "I am Karthik and I have two years of experience in sales.",
  "mistakes": [
    {
      "wrong": "Myself Karthik",
      "right": "I am Karthik",
      "type": "grammar",
      "explanation_tamil": "Myself is incorrect; you should use 'I am' to introduce yourself."
    },
    {
      "wrong": "and I am having",
      "right": "and I have",
      "type": "grammar",
      "explanation_tamil": "You should use 'have' for experience, not 'having'."
    }
  ]
}

{
  "corrected": "I have been working in this company since 2019.",
  "mistakes": [
    {
      "wrong": "I am working in this company since 2019.",
      "right": "I have been working in this company since 2019.",
      "type": "grammar",
      "explanation_tamil": "You should use 'have been working' to show continuous action from 2019 to now."
    }
  ]
}

{
  "corrected": "Please revert back to me today.",
  "mistakes": [
    {
      "wrong": "Please revert back to me today itself.",
      "right": "Please revert back to me today.","type":"grammar","explanation_tamil": "Adding 'itself' makes the sentence redundant and unnecessary in this context."
    }
  ]
}

{
  "corrected": "We discussed the budget, and he said it was fine.",
  "mistakes": [
    {
      "wrong": "discussed about",
      "right": "discussed",
      "type": "grammar",
      "explanation_tamil": "You do not need the word 'about' after 'discussed' in this context."
    },
    {
      "wrong": "he told that it is fine",
      "right": "he said it was fine",
      "type": "style",
      "explanation_tamil": "'Told that' is not professional; 'said' is better, and 'it is' should be 'it was'."
    }
  ]
}

